    if (step['uses'] != prewarmAction || step['with'] is! YamlMap) continue;
    final raw = '${(step['with'] as YamlMap)['targets'] ?? ''}'.trim();
    if (raw.isEmpty || raw == 'auto') continue;
    if (raw.contains(r'${{ matrix.')) {
      out.addAll(matrixValues ?? const <String>[]);
    } else {
      out.add(raw);
    }
  }
  return out;
}

